 async render(value){const serial=++this.serial,canvas=this.canvas;this.page=Math.max(1,Math.min(this.totalPages,Math.trunc(Number(value)||1)));const page=this.page;this.onPage?.(page);this.renderTask?.cancel();if(!canvas)return;this.onStatus?.('reading');canvas.parentElement.dataset.loading='true';try{const m=await this.manifest();if(serial!==this.serial)return;const {part,localPage}=partForPage(m,page),doc=await this.documentFor(part);if(serial!==this.serial||!canvas.isConnected)return;this.doc=doc;const p=await doc.getPage(localPage);if(serial!==this.serial||!canvas.isConnected)return;const natural=p.getViewport({scale:1}),available=Math.max(250,canvas.parentElement.clientWidth-28),width=Math.min(1100,available)*this.zoom,viewport=p.getViewport({scale:width/natural.width}),ratio=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(viewport.width*ratio);canvas.height=Math.floor(viewport.height*ratio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';canvas.setAttribute('aria-label','Textbook · PDF '+page);canvas.dataset.pdfPage=String(page);canvas.dataset.part=part.id;this.renderTask=p.render({canvasContext:canvas.getContext('2d'),viewport,transform:[ratio,0,0,ratio,0,0],background:'#ffffff'});await this.renderTask.promise;if(serial===this.serial){canvas.parentElement.dataset.loading='false';this.onStatus?.('ready');while(this.cache.size>2){const [id,old]=this.cache.entries().next().value;if(old===this.doc){this.cache.delete(id);this.cache.set(id,old);continue}this.cache.delete(id);await old.destroy()}}}catch(e){if(serial===this.serial&&e.name!=='RenderingCancelledException'){canvas.parentElement.dataset.loading='false';this.onStatus?.('readerError')}}}
